<?php
require __DIR__.'/db.php';$pageTitle='Results';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['action']??'';if($a==='create'){$st=$pdo->prepare('INSERT INTO results(enrollment_id,marks,remarks,evaluated_on) VALUES(?,?,?,?)');$st->execute([$_POST['enrollment_id'],$_POST['marks'],$_POST['remarks'],$_POST['evaluated_on']]);$msg='Result saved. Grade/status are assigned by trigger.';}elseif($a==='update'){$st=$pdo->prepare('UPDATE results SET marks=?,remarks=?,evaluated_on=? WHERE result_id=?');$st->execute([$_POST['marks'],$_POST['remarks'],$_POST['evaluated_on'],$_POST['result_id']]);$msg='Result updated by trigger.';}}catch(Throwable $e){$msg='Error: '.$e->getMessage();}}
$pending=$pdo->query("SELECT e.enrollment_id,CONCAT(s.first_name,' ',s.last_name) student_name,c.course_code FROM enrollments e JOIN students s ON s.student_id=e.student_id JOIN courses c ON c.course_id=e.course_id LEFT JOIN results r ON r.enrollment_id=e.enrollment_id WHERE r.result_id IS NULL ORDER BY e.enrollment_id")->fetchAll();$rows=$pdo->query('SELECT r.result_id,CONCAT(s.first_name," ",s.last_name) student_name,c.course_code,r.marks,r.grade,r.result_status,r.remarks,r.evaluated_on FROM results r JOIN enrollments e ON e.enrollment_id=r.enrollment_id JOIN students s ON s.student_id=e.student_id JOIN courses c ON c.course_id=e.course_id ORDER BY r.marks DESC')->fetchAll();include __DIR__.'/partials/header.php';
?>
<div class="hero"><div><h1>Results</h1><p>Marks are entered through the UI; a trigger calculates grade and pass/fail status.</p></div></div><?php if($msg): ?><div class="notice <?=str_starts_with($msg,'Error')?'error':'success'?>"><?=htmlspecialchars($msg)?></div><?php endif; ?><div class="form-card"><form method="post"><input type="hidden" name="action" value="create"><div class="form-grid"><div class="field"><label>Enrollment</label><select name="enrollment_id"><?php foreach($pending as $p): ?><option value="<?=$p['enrollment_id']?>"><?=htmlspecialchars($p['student_name'].' - '.$p['course_code'])?></option><?php endforeach; ?></select></div><div class="field"><label>Marks (0-100)</label><input type="number" step="0.01" min="0" max="100" name="marks" required></div><div class="field"><label>Evaluated On</label><input type="date" name="evaluated_on" value="<?=date('Y-m-d')?>"></div><div class="field full"><label>Remarks</label><textarea name="remarks" rows="2"></textarea></div><div class="field"><button class="btn">Save Result</button></div></div></form></div><div class="table-wrap"><table class="table"><tr><th>ID</th><th>Student</th><th>Course</th><th>Marks</th><th>Grade</th><th>Status</th><th>Remarks</th><th>Date</th></tr><?php foreach($rows as $r): ?><tr><td><?=$r['result_id']?></td><td><?=htmlspecialchars($r['student_name'])?></td><td><?=$r['course_code']?></td><td><?=$r['marks']?></td><td><strong><?=$r['grade']?></strong></td><td><span class="pill <?=$r['result_status']==='Pass'?'pass':'fail'?>"><?=$r['result_status']?></span></td><td><?=htmlspecialchars($r['remarks']??'')?></td><td><?=$r['evaluated_on']?></td></tr><?php endforeach; ?></table></div><?php include __DIR__.'/partials/footer.php'; ?>
